/* Course content. Edit explanations, examples and activities here; UI lives in app.js. */
const CLO = {
  1: 'Recommend the operating system for a given computing system based on efficient resource management.',
  2: 'Use Operating System as a resource manager to support multiprogramming.',
  3: 'Select the suitable process scheduling algorithm for a given computing problem.'
};
const card = (title, text, example) => ({title,text,example});
const step = (name, text, kind='') => ({name,text,kind});
const check = (q, options, answer, why) => ({q,options,answer,why});
const COURSES = {
  2: {
    title:'Structures of Operating System', short:'Structures of OS', kicker:'From code to execution',
    description:'Discover what an OS does, how programs ask for help, and how source code becomes a running program.',
    clos:[1,2], bridge:'In Week 1, we learned that the Operating System manages CPU, memory, storage and devices. Now we will see the services behind that work, how programs request them, and how the OS is organized.',
    question:'What services does the OS provide, how does a program request these services, and how is the OS organized?',
    outcome:'Follow a program from main.c to the CPU, then trace its requests through the OS.',
    lessons:[
      {id:'services', title:'Operating-System Services', question:'What happens when you type in VS Code while Teams is running?',
       explanation:'An operating system provides services that help programs run and help people use the computer. It also shares resources, detects problems and controls access. An OS service describes WHAT the OS provides.',
       example:'You type in VS Code: the keyboard supplies input and the screen displays output. The OS coordinates these I/O operations while also giving Teams CPU time and access to audio devices.',
       lab:'services', labTitle:'Your applications meet the hardware',
       cards:[card('Program Execution','Loads and starts programs, supports their execution, and handles completion.','Opening Chrome starts a program.'),card('I/O Operations','Coordinates input from devices and output to devices.','Keyboard input appears on the screen in VS Code.'),card('File-System Manipulation','Creates, reads, writes, organizes and deletes files and directories.','Save project.c on the SSD.'),card('Communication','Supports exchanging data between processes, on one computer or across a network.','Teams sends and receives meeting data.'),card('Error Detection','Detects and responds to problems in hardware or software.','The OS reports a failed storage read.'),card('Resource Allocation','Shares CPU time, memory, storage and devices among programs.','Chrome and Teams both receive CPU time.'),card('Protection','Controls which processes and users may access each resource.','One process cannot freely overwrite another process’s private memory.'),card('Security','Defends the system against unauthorized access and threats.','User authentication helps stop an unauthorized user from signing in.')],
       check:check('VS Code receives a keypress and updates the display. Which service is most directly involved?',['I/O Operations','Program Loading by the linker','Compilation','File deletion'],0,'The keyboard is an input device and the screen is an output device. The OS coordinates access to both.'),
       transition:'We know what the OS offers. Next, see how an application asks for a service.'},
      {id:'system-calls',title:'System Calls',question:'VS Code wants to open project.c. Can it directly command the SSD?',
       explanation:'A system call is a controlled way for an application to request a service from the Operating System. The request crosses from application execution into kernel work. The kernel checks the request, performs permitted work and returns a result. An application often calls a library API that makes the system call for it.',
       example:'VS Code requests that project.c be opened. The kernel checks access and locates the file. Opening returns a handle (or an error); separate read requests obtain file contents. The animation simplifies this open-and-read sequence into one journey.',
       lab:'flow',labTitle:'Follow a file request and its result',steps:[step('VS Code','The application wants to open and read project.c.','application'),step('System Call','An OS-specific call requests file access through a controlled entry point.','os'),step('Kernel','The kernel checks permissions and coordinates the request.','kernel'),step('Storage','When needed, the storage device supplies file data. A cache may already hold it.','hardware'),step('Kernel','The kernel processes the result and prepares a return value or error.','kernel'),step('VS Code','VS Code receives the result and can display the file contents.','application')],
       cards:[card('Process Control','Creates, ends or controls processes.','A shell requests creation of a new process.'),card('File Management','Opens, reads, writes or closes files.','A read request gets bytes from project.c.'),card('Device Management','Requests or controls device operations.','A program requests a device setting.'),card('Information Maintenance','Gets or sets system and process information.','A program requests the current time or its process ID.'),card('Communication','Exchanges information between processes.','A process sends bytes through a communication channel.'),card('Protection','Gets or changes permitted access to resources.','An authorized program changes a file’s access permissions.')],
       compare:[card('OS Service','WHAT the OS provides.','File access is a service.'),card('System Call','HOW an application requests kernel work.','A read system call requests file bytes.')],
       activity:{title:'Service or system call?',choices:['OS SERVICE','SYSTEM CALL'],items:[['Providing file access',0,'File access is a capability: WHAT the OS provides.'],['Calling read() to request bytes',1,'A call is a request mechanism: HOW the program asks.'],['Providing process creation',0,'This describes the service offered.'],['Invoking an OS call to create a process',1,'This describes a specific request to the OS.']]},
       check:check('Which statement correctly separates a service from a system call?',['Both mean a desktop utility.','A service is what the OS offers; a system call is how a program requests it.','A system call is a physical device.','A service always bypasses the kernel.'],1,'Services are capabilities. System calls are controlled request interfaces.'),transition:'Applications are not the only clients of the OS. Useful system programs use these services too.'},
      {id:'system-services',title:'System Services',question:'Is a file manager the same thing as the kernel’s file-access service?',
       explanation:'System services here means system programs or utilities: software that provides a convenient environment for developing, running and managing programs. These utilities use OS services, often through libraries and system calls. They are not all part of the kernel.',
       example:'You rename a folder in File Explorer. The utility provides the friendly interface; a system call requests a change; the OS file-system service performs permitted work.',
       lab:'flow',labTitle:'One task, three different roles',steps:[step('File Manager','A utility lets you select a folder and choose Rename.','application'),step('System Call','The utility requests the file-system operation.','os'),step('OS Service','The OS provides file-system manipulation.','os'),step('Kernel','Kernel code checks access and carries out the required work.','kernel')],
       cards:[card('File Management','Utilities help copy, rename, list and organize files.','File Explorer or a command-line copy tool.'),card('Status Information','Utilities show system state and resource use.','Task Manager displays CPU and memory usage.'),card('File Modification','Tools create or change file contents.','A text editor changes a configuration file.'),card('Programming Support','Tools help develop software.','Compilers and debuggers help build and inspect programs.'),card('Program Loading and Execution','Tools help prepare and start programs.','A shell launches an executable using OS facilities.'),card('Communication','Programs help users or processes exchange information.','A remote-login or messaging utility.')],
       compare:[card('Operating-System Services','Capabilities the OS provides.','Example: file manipulation.'),card('System Calls','Controlled requests for kernel services.','Example: a file-read request.'),card('System Services','Convenient system programs and utilities.','Example: a file manager.')],
       check:check('Task Manager shows CPU usage. In this lesson, what is Task Manager?',['A CPU core','A system call','A system program / utility','An object file'],2,'Task Manager is a user-facing utility that obtains information using OS facilities.'),transition:'Some system tools turn your source code into a program the OS can run.'},
      {id:'linkers-loaders',title:'Linkers and Loaders',question:'You wrote main.c. Can the CPU execute it directly?',
       explanation:'No. For this compiled C example, source code must be translated and prepared. The compiler produces an object file. The linker combines object files and required libraries into an executable. The loader places or maps the executable into memory and prepares it to run.',
       example:'main.c uses code from a library. Compilation creates main.o; linking combines or connects the required code to create an executable. Loading prepares its code and data in RAM. The CPU then executes machine instructions. Some library linking can be completed at load time or runtime.',
       lab:'flow',labTitle:'Build it, load it, run it',steps:[step('main.c','Human-readable C source code. It is not ready for direct CPU execution.'),step('Compiler','Translates source code into object code.'),step('main.o','An object file contains translated code; references may still need resolving.'),step('Linker','Combines object files, resolves references and connects required libraries.'),step('Executable','The program file produced by linking, ready to be prepared for execution.'),step('Loader','Maps or places the executable in memory and prepares execution.'),step('RAM','Holds the prepared program code and data.','memory'),step('CPU Execution','The CPU executes machine instructions.','cpu-key')],
       cards:[card('Compiler','Source Code → Object File','Creates main.o from main.c.'),card('Linker','Combines object files and required libraries to create an executable.','LINKER = creates executable.'),card('Loader','Places/prepares the executable in memory so it can execute.','LOADER = prepares executable in memory.')],
       activity:{title:'Who does this?',choices:['Compiler','Linker','Loader','CPU'],items:[['Creates main.o from main.c?',0,'The compiler translates source code into object code.'],['Combines object files and required libraries?',1,'The linker creates the executable.'],['Prepares the executable in RAM?',2,'The loader prepares the program’s memory image.'],['Executes machine instructions?',3,'The CPU performs instruction execution.']]},
       check:check('An executable exists on the SSD but has not been started. Which role prepares it in memory?',['Linker','Loader','Text editor','Printer'],1,'The linker has already created the executable. The loader prepares it in memory for execution.'),transition:'These tools rely on OS choices. How do designers decide what the OS should do?'},
      {id:'design',title:'Operating-System Design and Implementation',question:'How can an OS share the CPU fairly and still respond quickly?',
       explanation:'An OS needs careful design because many programs share limited resources. Designers balance goals such as efficiency, reliability, security and ease of use. Design is planning how the OS should work. Implementation is building the OS according to that design.',
       example:'A university lab computer may prioritize responsive interactive work. The policy decides which process should get CPU time. The mechanism saves the old execution state and restores the selected process’s state so CPU control can change.',
       lab:'flow',labTitle:'From a decision to an action',steps:[step('Design','Plan responsibilities and goals for sharing the CPU.'),step('Policy','Decide WHICH ready process should receive CPU time.','os'),step('Mechanism','Carry out the transfer of CPU control using OS facilities.','kernel'),step('Implementation','Build the code that realizes the design, policy and mechanism.')],
       cards:[card('Design','Planning how the OS should work.','Decide how responsibilities are divided.'),card('Implementation','Building the OS according to the design.','Write and integrate the kernel and supporting code.'),card('Policy','WHAT should be done?','Which process should receive CPU time?'),card('Mechanism','HOW should it be done?','How does the OS transfer CPU control to that process?')],
       activity:{title:'Policy or mechanism?',choices:['Policy','Mechanism'],items:[['Choose which process runs next.',0,'Choosing the desired outcome is policy.'],['Save and restore state to transfer CPU control.',1,'The facilities that carry out the decision are mechanisms.'],['Decide which users may read a file.',0,'The access rule is policy.'],['Check a request against access permissions.',1,'The permission-checking facility enforces the rule.']]},
       check:check('Why is separating policy from mechanism useful?',['It lets rules change without redesigning every underlying operation.','It removes the need for a kernel.','It makes source code directly executable.','It eliminates resource limits.'],0,'A mechanism can support different policies. Changing a decision rule need not require rebuilding every supporting facility.'),transition:'Design also determines how OS components fit together.'},
      {id:'structure',title:'Operating-System Structure',question:'Where does an application’s request go inside a computer system?',
       explanation:'OS structure describes how the operating system’s components are organized and how they interact. This simplified responsibility diagram places applications above OS services, the kernel and hardware. It is a learning model, not a claim that every real OS uses four separate implementation layers.',
       example:'A browser requests data. OS services provide communication and I/O; the kernel coordinates protected operations and drivers; hardware performs the physical work. Results travel back to the application.',
       lab:'layers',labTitle:'Explore the responsibility of each layer',
       cards:[card('Applications','Perform tasks for users and request OS help.','Chrome, Teams and VS Code.'),card('Operating-System Services','Offer program execution, I/O, files, communication and other capabilities.','These describe WHAT is provided.'),card('Kernel','The privileged core that manages resources and coordinates protected operations.','Handles system calls and works with drivers.'),card('Hardware','Physical resources that perform computation, storage and I/O.','CPU, RAM, SSD, keyboard and screen.')],
       check:check('Which component is the privileged core that coordinates protected resource access?',['A text file','A desktop icon','The kernel','A compiler warning'],2,'The kernel manages core resources and handles controlled requests for privileged operations.'),transition:'Now connect compilation, loading and OS interaction in one complete journey.'}
    ],
    journey:[step('Source Code','You write a program such as main.c.'),step('Compiler','Translates source into object code.'),step('Object File','Contains compiled code with references to resolve.'),step('Linker','Combines objects and required libraries.'),step('Executable','A runnable program file has been built.'),step('Loader','Prepares the program in memory.'),step('Memory','Code and data are available for execution.','memory'),step('Running Program','The CPU begins executing the program.','process'),step('System Call','The running program requests protected OS work.','os'),step('OS Service','The request asks for a capability, such as file access. This is a logical role, not a separate physical stop.','os'),step('Kernel','Kernel code performs or coordinates the requested service.','kernel'),step('Hardware','Devices carry out physical work when needed; the result returns to the program.','hardware')]
  },
  3: {
    title:'Processes',short:'Processes',kicker:'A program comes to life',description:'See how running programs share the CPU, move through a lifetime and communicate with each other.',clos:[2,3],
    bridge:'In Week 2, our executable was loaded into memory and started running. What does the OS call a running program? A PROCESS.',question:'What happens when several running programs all need the same CPU?',outcome:'Distinguish a program from a process and explain how processes are managed and communicate. Scheduling algorithms are studied later; here we build the concept.',
    lessons:[
      {id:'process-concept',title:'Process Concept',question:'Is the Chrome icon on your computer already a running process?',explanation:'A program is stored code and instructions. A process is a program currently executing, together with the state and resources needed for that execution. The OS manages each running process. Starting the same program more than once can create separate processes.',example:'Chrome installed on storage is a program. Start Chrome and running processes appear. Chrome, Teams, VS Code and Spotify can all be active. Modern browsers often use several processes; our single Chrome tile is a simplified example.',lab:'flow',labTitle:'From stored instructions to active work',steps:[step('Program','Chrome’s executable is stored on the computer. It is passive code.','application'),step('Start','The OS prepares memory and execution resources.'),step('Process','The program is now executing with its own execution state.','process')],cards:[card('Program','Stored code / instructions.','An executable saved on the SSD.'),card('Process','A program currently executing.','A running instance managed by the OS.'),card('Multiple processes','The OS manages many active programs.','Chrome, Teams, VS Code and Spotify.')],check:check('You save an executable but never start it. What is it?',['A running process','A stored program','A CPU core','A thread library'],1,'A saved executable is a program. It becomes part of a process when started for execution.'),transition:'Many active processes create competition for CPU time.'},
      {id:'scheduling',title:'Process Scheduling',question:'What happens if Chrome, Teams, VS Code and Spotify all want the CPU?',explanation:'CPU time is limited. Process scheduling selects a ready process to receive CPU time. A process that is ready can wait while another runs. Switching among processes helps the OS share the CPU as a resource manager. This demonstration uses one CPU core and a simple illustrative order, not a scheduling algorithm to memorize.',example:'While Teams handles a meeting, VS Code edits a file and Spotify plays music. The OS gives their runnable work opportunities to execute. Some processes may instead be waiting for input or another event.',lab:'scheduler',labTitle:'The CPU waiting area',cards:[card('Ready to run','The process can execute but is waiting for CPU time.','The tiles in our waiting area are ready.'),card('Running','The process currently has CPU time.','The tile inside the CPU is running.'),card('Resource manager','The OS decides how limited CPU time is shared.','Detailed scheduling algorithms come in a later week.')],check:check('On one CPU core, why do ready processes need scheduling?',['All can execute instructions at the exact same instant.','Only one execution stream can use that core at a time.','The linker chooses CPU time.','Processes never compete for resources.'],1,'The OS selects which ready work uses the core. Fast switching can make several applications feel active together.'),transition:'CPU time is only one part of a process’s lifetime.'},
      {id:'operations',title:'Operations on Processes',question:'What changes when you open, use and close VS Code?',explanation:'A process has a lifetime. Creation sets up a process and its resources. During execution, its instructions run whenever it receives CPU time. Termination ends the process and allows the OS to reclaim its resources. Create → Execute → Terminate summarizes lifetime operations, not every detailed process state.',example:'You open VS Code: the OS creates a process. You edit a file: the process executes and may wait for events. You close the application: its process terminates. Some applications also keep background helper processes.',lab:'flow',labTitle:'One application, one lifetime',steps:[step('Create','The user opens VS Code; the OS sets up a process.','process'),step('Execute','VS Code receives CPU time and runs; it may also wait for input.','cpu-key'),step('Terminate','Closing the application ends this example process and resources can be reclaimed.','os')],cards:[card('Create','Set up a new process.','Opening an application begins its lifetime.'),card('Execute','Run the program’s instructions.','The editor responds to typing.'),card('Terminate','End execution and release resources.','The user closes the example application.')],check:check('What normally happens after a process terminates?',['Its resources can be reclaimed by the OS.','Its source code must be erased.','It permanently owns the CPU.','It becomes a compiler.'],0,'Ending a process lets the OS reclaim its resources. The program file may remain on storage.'),transition:'A running process may need information from another process.'},
      {id:'ipc',title:'Interprocess Communication (IPC)',question:'Can two running processes communicate?',explanation:'Yes. Interprocess communication (IPC) allows processes to exchange information and coordinate their work. The two main approaches in this module are shared memory and message passing. Processes need a defined way to exchange data because they do not simply share all private resources automatically.',example:'One process prepares a result and another displays it. They can agree to use a common memory area, or send the result as a message.',lab:'flow',labTitle:'Two ways to cooperate',steps:[step('Process A','Prepares information needed by another process.','process'),step('IPC','Uses an agreed communication approach.','os'),step('Process B','Receives or reads the information and continues its work.','process')],cards:[card('Shared Memory','Communicate through a common memory area.','A writes data; B reads that area.'),card('Message Passing','Communicate by sending and receiving messages.','A sends data; B receives it.')],check:check('What is the purpose of IPC?',['To turn a core into RAM','To replace all programs with threads','To let processes exchange information and coordinate','To compile source code'],2,'IPC enables cooperation between running processes.'),transition:'First, watch processes exchange data through shared memory.'},
      {id:'shared-memory',title:'IPC in Shared-Memory Systems',question:'How can Process B read information written by Process A?',explanation:'With shared memory, the OS helps establish a common memory area that both processes can access. Process A writes into that region and Process B reads it. Once set up, ordinary data exchange can use memory access rather than sending each item as an OS message. Access still needs correct coordination.',example:'A data-processing application has one process produce a result and another display it. The producer writes “Result = 42” into their shared region; the display process reads it when it is ready.',lab:'shared',labTitle:'Write once, read from the common area',cards:[card('Process A','Writes information into the shared area.','The producer stores Result = 42.'),card('Shared Memory','A common region accessible to both processes.','Not all of either process’s private memory is shared.'),card('Process B','Reads information from that same area.','The consumer reads Result = 42.')],check:check('In shared-memory IPC, where does Process B get A’s data?',['From a common memory area','From a newly compiled object file','Only from a printer','From a separate CPU inside A'],0,'Both processes can access the agreed shared region. A writes there and B reads there.'),transition:'What if the processes exchange messages instead of reading the same area?'},
      {id:'message-passing',title:'IPC in Message-Passing Systems',question:'How can A communicate without using a common data area with B?',explanation:'Message passing lets processes send and receive information through communication facilities. A sends a message to B; B can send a response. The OS or communication runtime supports delivery. Message passing can be used locally or across a network.',example:'A calculation process receives a request containing two numbers. It calculates a result and sends a response to the requesting process.',lab:'flow',labTitle:'A message and a response',steps:[step('Process A','Prepares the message: please calculate 20 + 22.','process'),step('Message','The request travels through a communication channel.','os'),step('Process B','Receives the request and calculates 42.','process'),step('Response','A response containing 42 travels back.','os'),step('Process A','Receives and uses the result.','process')],compare:[card('Shared Memory','Common area: A writes, B reads.','The processes coordinate access to shared data.'),card('Message Passing','Messages: A sends, B receives.','A reply can carry the result back.')],activity:{title:'Which IPC approach?',choices:['Shared Memory','Message Passing'],items:[['Two processes read and write the same agreed memory region.',0,'Their common region is the communication medium.'],['A sends a request and B sends a reply.',1,'Information is exchanged as messages.'],['A writes a result into a shared buffer for B.',0,'B reads the shared buffer rather than receiving that value as a message.'],['A worker receives a task through a communication channel.',1,'Send/receive operations indicate message passing.']]},check:check('Which description best matches message passing?',['Every process can freely read every other process’s memory.','Processes exchange information by sending and receiving messages.','A linker places an executable in RAM.','Only one process can exist.'],1,'Message passing uses explicit exchanges through a communication channel.'),transition:'The request-and-response pattern is especially familiar on the web.'},
      {id:'client-server',title:'Communication in Client–Server Systems',question:'What happens after your browser requests a web page?',explanation:'A client process requests a service. A server process receives the request, does the requested work and returns a response. They can communicate on one machine or across a network. This is a practical use of process communication.',example:'Your browser is the client. It requests a course page from a web server. The server returns page content, and the browser displays it. Client and server describe roles in this exchange.',lab:'flow',labTitle:'Browser meets web server',steps:[step('Client','The browser prepares a request for a page.','process'),step('Request','The request travels to the web server.','os'),step('Server','The server receives the request and prepares page content.','process'),step('Response','The server returns the requested content or an error.','os'),step('Client','The browser receives the response and displays the page.','process')],cards:[card('Client','Initiates a request for a service.','A browser asks for a page.'),card('Server','Handles requests and returns responses.','A web server returns page content.')],check:check('In a normal browser-to-web-server exchange, which role begins the page request?',['Loader','Server response','Client','Compiler'],2,'The client browser initiates the request. The server handles it and replies.'),transition:'Connect running programs, CPU sharing and communication in the complete journey.'}
    ],journey:[step('Program','Stored instructions are ready to start.','application'),step('Process','A running program has state and resources.','process'),step('CPU Scheduling','The OS selects ready work for CPU time.','cpu-key'),step('Process Operations','Creation, execution and termination describe the lifetime. This summary groups concepts; IPC occurs during execution.','os'),step('IPC','Running processes exchange information and coordinate.','os'),step('Shared Memory / Message Passing','They use a common memory area or send and receive messages.','memory'),step('Client–Server Communication','A client requests a service and a server responds.','process')]
  },
  4: {
    title:'Threads & Concurrency',short:'Threads & Concurrency',kicker:'Multiple activities, one process',description:'Explore threads inside a process, distribute work across cores, and understand how thread management fits together.',clos:[2],bridge:'Last week we learned about processes. Can ONE process perform several activities? Yes: threads provide execution activities inside a process.',question:'How can one application display a page, download data and respond to you?',outcome:'Explain how threads share a process, how cores execute work, and why more threads are not automatically faster.',
    lessons:[
      {id:'process-thread',title:'From Process to Thread',question:'Can ONE process perform several activities?',explanation:'A process is a running program. A thread is an execution activity inside a process. Threads in the same process share resources such as code and data, while each has its own execution state, including a stack and current instruction position. Several threads let a process make progress on multiple activities.',example:'In a simplified Chrome process, threads display the page, download data and respond to the user. Real browsers use multiple processes as well as threads; this diagram isolates the activities inside one process.',lab:'threads',labTitle:'One process, multiple threads',cards:[card('Process','The running program and its resources.','Our outer Chrome box is the process.'),card('Thread','An execution activity inside that process.','Each moving track represents one thread.'),card('Shared resources','Threads in one process can use the same code and data.','They must coordinate when updating shared data.')],check:check('Which description fits a thread?',['A physical CPU core','An execution activity within a process','A program file that cannot run','A separate operating system'],1,'A thread executes within a process and shares many of the process’s resources.'),transition:'Several threads can make progress together. Multiple cores can also execute work at the same instant.'},
      {id:'multicore',title:'Multicore Programming',question:'What changes when a CPU has four cores instead of one?',explanation:'A multicore CPU has multiple execution cores. Different cores can execute different threads at the same time. Concurrency means activities make progress over overlapping time periods; parallelism means work executes at the same instant. One core can support concurrency by switching. Multiple cores make parallel execution possible when the work can be divided.',example:'An application has independent display, download, calculation and input tasks. Assigning suitable work to different cores may improve responsiveness or throughput. Actual placement is managed by the OS; this activity lets you explore the idea.',lab:'cores',labTitle:'Assign independent tasks to four cores',cards:[card('Concurrency','Activities make progress over overlapping periods.','One core may switch between activities.'),card('Parallelism','Activities execute at the same instant.','Two cores run two threads simultaneously.'),card('Multicore work','Divide useful work so available cores can help.','Extra cores help only when work and resources allow it.')],check:check('Which situation demonstrates parallel execution?',['One core switches between two threads.','Two cores execute two threads at the same instant.','An executable sits on storage.','A program waits without executing.'],1,'Simultaneous execution on different cores is parallelism. Interleaving on one core is concurrency without simultaneous execution.'),transition:'How do application threads connect to the threads managed by the kernel?'},
      {id:'models',title:'Multithreading Models',question:'Must every user thread map to a different kernel thread?',explanation:'Not always. A multithreading model describes the relationship between user threads and kernel threads. The runtime or thread library manages user threads; the OS schedules kernel threads. The mapping affects how execution can use the available cores.',example:'If many user threads map to one kernel thread, that group cannot run on several cores at once. Mapping work to multiple kernel threads can allow parallel execution when multiple cores are available.',lab:'models',labTitle:'Explore user-to-kernel thread mappings',cards:[card('Many-to-One','Several user threads map to one kernel thread.','The group has only one kernel execution path.'),card('One-to-One','Each user thread maps to a corresponding kernel thread.','Multiple kernel threads can be scheduled on different cores.'),card('Many-to-Many','Multiple user threads map across multiple kernel threads.','A runtime shares user work across a set of kernel threads.')],activity:{title:'Guess the Model',choices:['Many-to-One','One-to-One','Many-to-Many'],items:[['Three user threads share one kernel thread.',0,'Many user threads map to one kernel thread.'],['Each of three user threads has its own kernel thread.',1,'Every user thread has a corresponding kernel thread.'],['Many user threads are managed across a pool of kernel threads.',2,'Multiple user threads map across multiple kernel threads.']]},check:check('Why can a Many-to-One group not run its user threads on several cores at once?',['Its group has only one kernel thread to schedule.','It always has one user thread.','It has no process.','Its source code is already compiled.'],0,'Multiple cores need multiple schedulable execution paths. This group provides only one kernel thread.'),transition:'Programmers use libraries to create and manage these execution activities.'},
      {id:'libraries',title:'Thread Libraries',question:'How does a programmer create and manage threads without building everything from scratch?',explanation:'A thread library provides functions and tools that programmers can use to create and manage threads. It may help start a thread, wait for it to finish and manage its lifecycle. How the library is implemented and mapped to kernel threads can vary.',example:'A programmer uses a thread library to start background calculation while the interface stays responsive. POSIX threads, Windows threading facilities and Java thread APIs are familiar examples; API syntax is outside this lesson.',lab:'flow',labTitle:'Tools for creating execution activities',steps:[step('Programmer','Identifies activities the application needs to perform.','application'),step('Thread Library','Provides functions for creating and managing threads.','os'),step('Threads','The created activities execute inside the process.','thread-key')],cards:[card('Create','Start an execution activity.','Begin a background calculation.'),card('Manage','Coordinate the thread lifecycle.','Wait for a worker to finish before using its final result.')],check:check('What does a thread library provide?',['Physical CPU cores','Tools and functions to create and manage threads','A replacement for all OS services','An executable linker only'],1,'Thread libraries offer programming support for thread creation and management.'),transition:'Sometimes programmers can describe tasks and let a framework manage more of the thread details.'},
      {id:'implicit',title:'Implicit Threading',question:'Must a programmer manually create and manage every thread?',explanation:'With explicit threading, the programmer directly handles more thread creation and management. With implicit threading, a compiler, runtime or framework handles more of those details. The programmer still identifies useful work and must write correct code; automatic management does not remove responsibility for shared data.',example:'Explicit: the programmer creates worker threads for a set of tasks. Implicit: the programmer submits tasks to a framework, which chooses available worker threads. A managed task pool is a conceptual example.',lab:'implicit',labTitle:'Who does more of the management?',compare:[card('Programmer Does More','Explicit threading: directly create and manage threads.','The programmer chooses thread lifecycle operations.'),card('System Does More','Implicit threading: a framework/runtime manages more thread details.','The programmer supplies work; the framework assigns workers.')],check:check('Which best illustrates implicit threading?',['A programmer manually manages every thread operation.','A framework assigns submitted tasks to worker threads.','A program cannot contain threads.','A linker chooses all runtime CPU turns.'],1,'The framework handles more of the mapping and management rather than requiring direct management of every worker.'),transition:'Whichever approach is used, shared resources require care.'},
      {id:'issues',title:'Threading Issues',question:'Will adding more threads always make your program faster?',explanation:'No. Threads share resources and may access the same data. Their execution must be coordinated correctly. If two threads update data using an old value, work can be lost. Thread management also costs time; a limited number of cores and competition for resources can limit improvement. We will study detailed synchronization techniques in later weeks.',example:'A shared counter starts at 0. Two threads both read 0, both calculate 1 and both write 1. Two increments were intended, but the final value is only 1. A coordinated order can let the second thread read the first thread’s update and finish at 2.',lab:'issues',labTitle:'Two threads, one shared value',cards:[card('Shared resources','Threads in one process may use the same data and resources.','Both workers update one counter.'),card('Correct coordination','The order of access must preserve correct results.','A later update must account for an earlier one.'),card('Performance limits','More Threads ≠ Automatically Better Performance.','Management work and resource competition can outweigh benefits.')],check:check('Why might additional threads fail to improve performance?',['Threads remove all resource limits.','More threads guarantee more cores.','Management costs and resource competition can offset useful work.','A thread cannot execute instructions.'],2,'Threads are useful only when the available work and resources justify their management costs.'),transition:'Bring threads, cores, models and management together in the final weekly journey.'}
    ],journey:[step('Process','A running program owns resources.','process'),step('Multiple Threads','Execution activities share those process resources.','thread-key'),step('Multicore CPU','Different cores can execute suitable work simultaneously.','cpu-key'),step('Multithreading Models','User threads map to kernel threads in different ways.'),step('Thread Libraries','Programming tools create and manage threads.'),step('Implicit Threading','A runtime or framework takes on more management.'),step('Threading Issues','Correct shared-data coordination and resource limits still matter.')]
  }
};
